import{M as a}from"./chunks/MicroarchDiagram.DrgIqI9i.js";import{o,c as d,a2 as e,E as r}from"./chunks/framework.CNQbXYGB.js";const h=JSON.parse('{"title":"1.2 · CU、Wavefront 与计算路径","description":"","frontmatter":{"outline":2},"headers":[],"relativePath":"02-compute/cu-and-simt.md","filePath":"02-compute/cu-and-simt.md"}'),n={name:"02-compute/cu-and-simt.md"},m=Object.assign(n,{setup(l){return(s,t)=>(o(),d("div",null,[t[0]||(t[0]=e('<h1 id="_1-2-·-cu、wavefront-与计算路径" tabindex="-1">1.2 · CU、Wavefront 与计算路径 <a class="header-anchor" href="#_1-2-·-cu、wavefront-与计算路径" aria-label="Permalink to &quot;1.2 · CU、Wavefront 与计算路径&quot;">​</a></h1><p>Block 分到 CU 后，CU 会安排其中的 wave 执行。先拆开看这个计算单元里有哪些资源，再看向量加法的尾部线程怎样执行。</p><div class="info custom-block"><p class="custom-block-title">先认识这几个词</p><p><strong>CU</strong>（Compute Unit）是承载 Block 的硬件计算单元。<strong>ALU</strong>（Arithmetic Logic Unit，算术逻辑单元）是计算路径中的部件，做加法、比较、位运算等。<strong>寄存器</strong>保存指令要用的值。<strong>LDS</strong>（Local Data Share）是 CU 上的片上共享存储，同一 Block 的线程可用它交换数据。</p></div><h2 id="_1-cu-怎么组织执行" tabindex="-1">1. CU 怎么组织执行 <a class="header-anchor" href="#_1-cu-怎么组织执行" aria-label="Permalink to &quot;1. CU 怎么组织执行&quot;">​</a></h2><p>一个 CU 需要做三件事：让 wave 驻留，选择哪条指令可以发射，再交给合适的执行路径。CU 里有调度器、寄存器和不同用途的执行路径，ALU 负责其中的算术与逻辑运算。</p><ul><li><strong>设备分派 Block。</strong> 设备决定给哪个 CU 分配一个 Block。</li><li><strong>CU 调度 wave。</strong> 已驻留的 Wave A 等数据时，若 Wave B 就绪且相应执行资源可用，调度器可让 Wave B 发射指令。Wave A 的执行状态仍然保留。</li></ul><p>这是功能分工。一个线程的逻辑 lane 编号用于表示它在 wave 里的位置，物理 ALU 会被硬件反复用于不同指令和线程组。具体资源组织随架构而变。<a href="https://rocm.docs.amd.com/projects/HIP/en/docs-6.3.3/understand/hardware_implementation.html" target="_blank" rel="noreferrer">HIP 硬件实现</a></p><h2 id="cu-内各路径做什么" tabindex="-1">2. 先看寄存器，再看执行路径 <a class="header-anchor" href="#cu-内各路径做什么" aria-label="Permalink to &quot;2. 先看寄存器，再看执行路径 {#cu-内各路径做什么}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>寄存器</th><th>英文全称</th><th>存什么</th></tr></thead><tbody><tr><td>SGPR</td><td>Scalar General-Purpose Register</td><td>标量通用寄存器。一个 wave 共用的值，例如编译器可证明统一的基地址或参数。</td></tr><tr><td>VGPR</td><td>Vector General-Purpose Register</td><td>向量通用寄存器。一个 wave 内可以每个 lane 各有一个值，例如各线程的数组索引、读到的数据或运算结果。</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">想一想这个值有没有随 lane 变化</p><p>向量加法中，数组基地址对一个 wave 可以相同，<code>a[i]</code> 和 <code>b[i]</code> 随线程变化。这个区别有助于理解 SGPR 和 VGPR 的分工，具体放在哪个寄存器由编译器和目标指令决定。</p></div><table tabindex="0"><thead><tr><th>功能</th><th>主要职责</th></tr></thead><tbody><tr><td><strong>SALU</strong>（Scalar Arithmetic Logic Unit，标量算术逻辑单元）</td><td>处理 wave 级的标量运算和部分控制，例如统一的地址或循环状态。</td></tr><tr><td><strong>VALU</strong>（Vector Arithmetic Logic Unit，向量算术逻辑单元）</td><td>对有效 lane 各自的数据运算，例如向量加法中的 FP32 加法。</td></tr><tr><td><strong>VMEM</strong>（Vector Memory Operations，向量访存）</td><td>发出按 lane 的内存操作，例如读取 A、B 或写回 C。</td></tr><tr><td>特殊函数路径（常称 <strong>SFU</strong>，Special Function Unit）</td><td>部分目标提供指数、倒数或平方根倒数等专门指令。具体映射看目标 ISA。</td></tr></tbody></table><p>矩阵块的乘加还有专门的指令路径，称为 <strong>MMAC</strong>（Matrix Multiply-Accumulate），见 <a href="./mmac.html">1.5 MMAC</a>。</p>',12)),r(a,{kind:"compute"}),t[1]||(t[1]=e('<h2 id="_3-simt-与-simd-对应哪一层" tabindex="-1">3. SIMT 与 SIMD 对应哪一层 <a class="header-anchor" href="#_3-simt-与-simd-对应哪一层" aria-label="Permalink to &quot;3. SIMT 与 SIMD 对应哪一层&quot;">​</a></h2><ul><li><strong>SIMT</strong>（Single Instruction, Multiple Threads，单指令多线程）描述编程模型。HIP 里每个线程有自己的编号和数据，硬件把同一个 wave 中参与的线程组织在一条指令流中。</li><li><strong>SIMD</strong>（Single Instruction, Multiple Data，单指令多数据）描述执行方式。一条指令对多份数据做同一种操作。向量加法里，参与的 lane 执行同一种加法，各自用自己的操作数。</li></ul><p>在一维 Block 中，<code>wave_id = threadIdx.x / warpSize</code>，<code>lane_id = threadIdx.x % warpSize</code>。在 BW100 的 Wave64 上，线程 130 是 <strong>Wave 2 的 Lane 2</strong>。例如，早期部分 GCN 的 SIMD 物理宽度是 16，一条覆盖 64 个逻辑 lane 的普通向量指令可能分成数批处理。观察 BW100 时要分别核对 wave 的逻辑宽度、具体指令的物理执行方式、等待结果的延迟、以及单位时间能完成的吞吐。<a href="https://rocm.docs.amd.com/projects/HIP/en/docs-6.3.3/understand/programming_model.html" target="_blank" rel="noreferrer">HIP 编程模型</a></p><h2 id="一个-wave-怎么执行" tabindex="-1">4. 尾部 wave 如何处理不同条件 <a class="header-anchor" href="#一个-wave-怎么执行" aria-label="Permalink to &quot;4. 尾部 wave 如何处理不同条件 {#一个-wave-怎么执行}&quot;">​</a></h2><p>在 1.1 的最后一个 wave 中，40 个 lane 的索引满足 <code>i &lt; count</code>。同一 wave 中条件不同时，参与向量指令的 lane 可由执行掩码控制。</p>',5)),r(a,{kind:"lanes"}),t[2]||(t[2]=e('<table tabindex="0"><thead><tr><th>名称</th><th>作用</th></tr></thead><tbody><tr><td><strong>EXEC</strong>（Execution Mask）</td><td>保存当前参与向量执行的 lane 掩码。</td></tr><tr><td><strong>VCC</strong>（Vector Condition Code）</td><td>可保存向量比较等操作的逐 lane 结果。</td></tr><tr><td><strong>SCC</strong>（Scalar Condition Code）</td><td>保存某些标量指令产生的条件状态，可用于标量控制流。</td></tr></tbody></table><p>向量加法在 BW100 上实际生成了向量比较和 <code>s_and_saveexec_b64</code>。它保存旧 EXEC，再用比较结果更新参与的 lane。含 <code>else</code> 的控制流可能分别用两组掩码执行两侧，再在汇合处恢复原掩码。全 wave 一致的条件有机会用标量分支，短分支也可能被编译成诸如 <code>v_cndmask_b32</code> 的谓词选择指令，性能要结合实际汇编判断。<a href="./../01-overview/software-stack.html#动手运行">向量加法编译命令</a> · <a href="./../labs/lab03-branch-divergence.html">E03 分支实验</a> · <a href="https://llvm.org/docs/AMDGPUUsage.html" target="_blank" rel="noreferrer">LLVM AMDGPU 寄存器参考</a></p><h2 id="_5-思考题" tabindex="-1">5. 思考题 <a class="header-anchor" href="#_5-思考题" aria-label="Permalink to &quot;5. 思考题&quot;">​</a></h2><p>仍看向量加法的最后一个 wave。假设编译器先比较 <code>i &lt; 1000</code>，再按比较结果更新 EXEC，哪几个 lane 会执行数组读写？数组里每个线程拿到的 <code>a[i]</code> 用 SGPR 还是 VGPR 表示更合适？</p><details class="details custom-block"><summary>查看答案</summary><p>这个 wave 从索引 960 开始，Lane 0–39 对应索引 960–999，会执行数组读写。Lane 40–63 对应越界索引。<code>a[i]</code> 随 lane 变化，适合用 <strong>VGPR</strong> 表示；可以证明整个 wave 统一的值才有机会走 SGPR。</p></details><p><a href="./../03-memory/memory-hierarchy.html">继续 1.3 · 数据从哪里来</a></p>',6))]))}});export{h as __pageData,m as default};
